INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Anwendungsschicht Teil des OSI-Modells?', 2, '[{"text": "Ja", "correct": true, "because": "Schicht 7"}, {"text": "Nein", "correct": false, "because": "Sie ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die Anwendungsschicht?', 3, '[{"text": "Bereitstellung von Netzwerkdiensten für Anwendungen", "correct": true, "because": "Schnittstelle zum Nutzer"}, {"text": "Daten physisch übertragen", "correct": false, "because": "Bitübertragungsschicht"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Darunterliegende Schicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Anwendungsschicht ist Schicht 7 im OSI-Modell. b) Sie ist für die Hardware zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Bitübertragungsschicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle arbeiten auf der Anwendungsschicht?', 4, '[{"text": "HTTP", "correct": true, "because": "Webzugriff"}, {"text": "IP", "correct": false, "because": "Netzwerkschicht"}, {"text": "FTP", "correct": true, "because": "Dateiübertragung"}, {"text": "SMTP", "correct": true, "because": "E-Mail-Versand"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Netzwerk ohne Anwendungsschicht funktionieren?', 2, '[{"text": "Ja", "correct": true, "because": "Tieferliegende Schichten"}, {"text": "Nein", "correct": false, "because": "Anwendungen fehlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Anwendungsschicht?', 3, '[{"text": "Schnittstelle zwischen Nutzer und Netzwerk", "correct": true, "because": "Bietet Dienste"}, {"text": "Daten physisch übertragen", "correct": false, "because": "Bitübertragungsschicht"}, {"text": "Routing von Paketen", "correct": false, "because": "Netzwerkschicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Anwendungsschicht nur für Softwareentwickler relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Administratoren"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat HTTP auf der Anwendungsschicht?', 3, '[{"text": "Webseiten übertragen", "correct": true, "because": "Hypertext-Übertragung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "HTTPS-Aufgabe"}, {"text": "Netzwerkadressen zuweisen", "correct": false, "because": "Netzwerkschicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Anwendungsschicht interagiert mit dem Nutzer. b) Sie ist für die Kabelverbindung zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Bitübertragungsschicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Anwendungsschicht?', 3, '[{"text": "Keine nutzerorientierten Dienste", "correct": true, "because": "Anwendungen fehlen"}, {"text": "Netzwerk wird schneller", "correct": false, "because": "Unsinn"}, {"text": "Datenübertragung unmöglich", "correct": false, "because": "Tieferliegende Schichten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Anwendungsschicht ohne darunterliegende Schichten arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Transport"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein Anwendungsschicht-Protokoll?', 3, '[{"text": "DNS", "correct": true, "because": "Namensauflösung"}, {"text": "Ethernet", "correct": false, "because": "Sicherungsschicht"}, {"text": "IP", "correct": false, "because": "Netzwerkschicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Anwendungsschicht nur für Internetdienste relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokale Dienste"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Anwendungsschicht?', 4, '[{"text": "Nutzerinteraktion", "correct": true, "because": "Dienste für Anwender"}, {"text": "Physische Übertragung", "correct": false, "because": "Bitübertragungsschicht"}, {"text": "Protokolle wie HTTP", "correct": true, "because": "Standarddienste"}, {"text": "Datenformatierung", "correct": true, "because": "Anwendungsspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Anwendungsschicht dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll gehört zur Anwendungsschicht?', 3, '[{"text": "POP3", "correct": true, "because": "E-Mail-Abruf"}, {"text": "TCP", "correct": false, "because": "Transportschicht"}, {"text": "UDP", "correct": false, "because": "Transportschicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Anwendungsschicht ohne Nutzeranwendungen funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Anwendungen nötig"}, {"text": "Ja", "correct": false, "because": "Zweck fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Anwendungsschicht?', 3, '[{"text": "Anwendungsanforderungen", "correct": true, "because": "Bestimmen Protokolle"}, {"text": "Kabeltyp", "correct": false, "because": "Bitübertragungsschicht"}, {"text": "Monitorgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Anwendungsschicht liefert Dienste wie E-Mail. b) Sie ist für das Routing zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Netzwerkschicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Anwendungsschicht?', 3, '[{"text": "Nutzung von Netzwerkdiensten", "correct": true, "because": "Fördert Funktionalität"}, {"text": "Maximale Isolation", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Nutzerinteraktion", "correct": false, "because": "Fördert Dienste"}]');